// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.permissionimport timber.log.Timberimport android.content.ComponentNameimport android.content.Contextimport android.content.Intentimport android.content.SharedPreferencesimport android.provider.Settingsimport android.text.TextUtilsimport androidx.security.crypto.EncryptedSharedPreferencesimport androidx.security.crypto.MasterKey/** * NOUS — Accessibility Permission Manager (Module 9 v1 — Step 9.1 + P2 fix). * * Manages the AccessibilityService permission state with REAL Android APIs: *  - [Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES] — checks if NOUS is enabled *  - [Settings.Secure.ACCESSIBILITY_ENABLED] — checks if accessibility is on *  - Intent deep-link to Settings → Accessibility → NOUS *  - **24h cooldown on denial** — persisted to [EncryptedSharedPreferences] *    (P2 fix; previously this was a count-based `requestCount < 3` gate, *    which the spec called out as wrong — the spec asks for time-based *    24h cooldown so we don't nag the user) * * ## Why EncryptedSharedPreferences (not DataStore)? * * DataStore would be too heavy here — it pulls in coroutines + protobuf * + a separate process for reads. The cooldown is a single `Long` timestamp * read on every rationale decision; EncryptedSharedPreferences is a thin * wrapper around `SharedPreferences` with AES-256-GCM at rest. Perfect for * a single value. * * ## Triple Opt-in Flow (per strategy v1 §"Privacy & Security") * *  1. NOUS dialog: "NOUS needs Accessibility to auto-send WhatsApp messages..." *  2. Android Settings: User navigates to Settings → Accessibility → NOUS → Enable *  3. Persistent notification: "NOUS Agent is active. Tap to stop." * * ## State Machine * * ``` * NOT_REQUESTED → user says "enable" *   → REQUESTING (NOUS dialog shown) *   → user taps "Enable" *   → SETTINGS_OPENED (deep-link to Settings) *   → user enables in Settings *   → GRANTED (service connected) *   OR *   → user cancels / doesn't enable *   → DENIED (24h cooldown — recordDenial()) *   → before 24h: shouldShowRationale() == false (don't nag) *   → after 24h: shouldShowRationale() == true (re-prompt allowed) * ``` * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Privacy: Triple Opt-in</a> */class AccessibilityPermissionManager(    private val context: Context,) {    companion object {        private const val TAG = "A11yPermission"        /** The NOUS accessibility service component name. */        val SERVICE_COMPONENT = ComponentName(            "com.roshan.persona",            "com.roshan.persona.agent.accessibility.NousAccessibilityService",        )        /** EncryptedSharedPreferences file name for the cooldown state. */        private const val PREFS_FILE = "nous_a11y_cooldown_prefs"        /** Preference key for the wall-clock timestamp (ms) of the last denial. */        private const val KEY_LAST_DENIED_MS = "last_denied_ms"        /** Preference key for the wall-clock timestamp (ms) of the last grant. */        private const val KEY_LAST_GRANTED_MS = "last_granted_ms"        /** 24-hour cooldown window in milliseconds. */        const val COOLDOWN_MS = 24L * 60L * 60L * 1000L    }    /**     * Lazy-initialised [EncryptedSharedPreferences] instance.     *     * Lazy because:     *  - Most [AccessibilityPermissionManager] calls are read-only state     *    checks (`isAccessibilityEnabled()`) that don't touch the cooldown.     *  - The first EncryptedSharedPreferences instantiation does keystore     *    IO (master-key generation) — deferring it until actually needed     *    saves ~30ms of cold-start time.     *     * On keystore failure (extremely rare on real devices, but possible on     * emulators with broken keystore), we fall back to plain `SharedPreferences`     * so the cooldown at least keeps working. A `Timber.e` is logged.     */    private val cooldownPrefs: SharedPreferences by lazy {        try {            val masterKey = MasterKey.Builder(context)                .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)                .build()            EncryptedSharedPreferences.create(                context,                PREFS_FILE,                masterKey,                EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,                EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM,            )        } catch (e: Exception) {            Timber.tag(TAG).e(e, "EncryptedSharedPreferences init failed — falling back to plain prefs (DEV ONLY).")            context.getSharedPreferences("${PREFS_FILE}.fallback", Context.MODE_PRIVATE)        }    }    /**     * Check if the NOUS AccessibilityService is enabled (REAL Android API).     *     * Uses [Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES] to check if our     * service is in the list of enabled accessibility services.     *     * @return true if the service is enabled.     */    fun isAccessibilityEnabled(): Boolean {        // Check if accessibility is enabled at all.        val accessibilityEnabled = try {            Settings.Secure.getInt(                context.contentResolver,                Settings.Secure.ACCESSIBILITY_ENABLED,            )        } catch (e: Settings.SettingNotFoundException) {            0        }        if (accessibilityEnabled != 1) {            return false        }        // Check if NOUS is in the list of enabled services.        val enabledServices = Settings.Secure.getString(            context.contentResolver,            Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES,        ) ?: return false        val serviceName = SERVICE_COMPONENT.flattenToString()        val flatName = SERVICE_COMPONENT.flattenToShortString()        val isEnabled = enabledServices.split(":").any { service ->            service.equals(serviceName, ignoreCase = true) ||            service.equals(flatName, ignoreCase = true)        }        Timber.tag(TAG).d("Accessibility enabled: $isEnabled (enabledServices=$enabledServices).")        return isEnabled    }    /**     * Open the Android Settings → Accessibility screen (REAL Android API).     *     * This deep-links the user to the Accessibility settings where they can     * find NOUS and enable it.     *     * @return true if the intent was launched.     */    fun openAccessibilitySettings(): Boolean {        return try {            val intent = Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS).apply {                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)            }            context.startActivity(intent)            Timber.tag(TAG).i("Opened Accessibility Settings.")            true        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to open Accessibility Settings.", t)            false        }    }    /**     * Get the rationale message to show to the user (first opt-in).     *     * This is the message shown in the NOUS dialog before deep-linking to Settings.     */    fun getRationaleMessage(): String = """        NOUS needs Accessibility permission to:        • Auto-send WhatsApp/Telegram messages (finds + clicks the Send button)        • Read what's on your screen (for the Visual Screen Reader)        • Control system actions (torch, back, home)        NOUS NEVER:        • Reads passwords or banking apps        • Reads your message content (only button text like "Send")        • Uploads any data to the cloud        You'll be taken to Android Settings to enable it.        You can disable it anytime in Settings → Accessibility → NOUS.    """.trimIndent()    /**     * Get the TTS message to speak to the user.     */    fun getSpokenMessage(): String =        "I need Accessibility permission to automate tasks and read your screen. " +        "I never read passwords or banking apps. I'll open Settings for you to enable it."    /**     * Get the persistent notification text (shown when service is active).     */    fun getPersistentNotificationTitle(): String = "NOUS Agent is active"    fun getPersistentNotificationText(): String = "Tap to stop. NOUS is monitoring screen for automation."    /**     * Get the denial message (when user cancels or doesn't enable).     */    fun getDenialMessage(): String =        "Accessibility permission not enabled. You can enable it later in Settings → Accessibility → NOUS."    /**     * Check if we should show the rationale again (24h cooldown — P2 fix).     *     * Returns true if either:     *  - No denial has ever been recorded (first run), OR     *  - The last denial was at least [COOLDOWN_MS] (24h) ago.     *     * Real implementation: reads `lastDeniedMs` from [EncryptedSharedPreferences]     * and compares to `System.currentTimeMillis()`.     *     * This replaces the previous count-based `requestCount < 3` gate, which     * the spec called out as wrong.     */    fun shouldShowRationale(): Boolean {        val lastDenied = cooldownPrefs.getLong(KEY_LAST_DENIED_MS, 0L)        if (lastDenied == 0L) {            // Never denied before — first run, rationale is appropriate.            return true        }        val now = System.currentTimeMillis()        val elapsed = now - lastDenied        val shouldShow = elapsed >= COOLDOWN_MS        Timber.tag(TAG).d("shouldShowRationale: elapsed=${elapsed}ms, cooldown=${COOLDOWN_MS}ms → $shouldShow.")        return shouldShow    }    /**     * Legacy count-based rationale check — DEPRECATED, kept for source     * compatibility with existing callers.     *     * Internally delegates to [shouldShowRationale] (time-based) AND requires     * `requestCount < 3`. So a caller that increments requestCount every     * attempt will eventually hit the count cap regardless of time, while     * also respecting the 24h cooldown.     *     * New callers should use [shouldShowRationale] (no args) instead.     */    @Deprecated("Use the no-arg shouldShowRationale() — it's time-based per spec.", replaceWith = ReplaceWith("shouldShowRationale()"))    fun shouldShowRationale(requestCount: Int): Boolean =        shouldShowRationale() && requestCount < 3    /**     * Record that the user denied accessibility permission at the current     * wall-clock time. Persists to [EncryptedSharedPreferences] so the     * cooldown survives process death + device reboot.     *     * Call this when the user explicitly cancels the rationale dialog OR     * returns from Settings without enabling the service.     */    fun recordDenial() {        val now = System.currentTimeMillis()        try {            cooldownPrefs.edit().putLong(KEY_LAST_DENIED_MS, now).apply()            Timber.tag(TAG).i("Recorded accessibility denial at $now (24h cooldown active).")        } catch (e: Exception) {            Timber.tag(TAG).e(e, "Failed to persist denial timestamp — cooldown will be lost on restart.")        }    }    /**     * Record that the user granted accessibility permission at the current     * wall-clock time. Clears any prior denial timestamp so the next time     * the user disables + we re-prompt, the 24h cooldown starts fresh.     */    fun recordGrant() {        val now = System.currentTimeMillis()        try {            cooldownPrefs.edit()                .putLong(KEY_LAST_GRANTED_MS, now)                .remove(KEY_LAST_DENIED_MS)                .apply()            Timber.tag(TAG).i("Recorded accessibility grant at $now — cleared denial cooldown.")        } catch (e: Exception) {            Timber.tag(TAG).e(e, "Failed to persist grant timestamp.")        }    }    /**     * Get the wall-clock timestamp (ms) of the last recorded denial, or 0     * if no denial has ever been recorded. Exposed for the Settings → Debug     * → Permission state screen.     */    fun getLastDeniedMs(): Long = cooldownPrefs.getLong(KEY_LAST_DENIED_MS, 0L)    /**     * Get the wall-clock timestamp (ms) of the last recorded grant, or 0     * if no grant has ever been recorded.     */    fun getLastGrantedMs(): Long = cooldownPrefs.getLong(KEY_LAST_GRANTED_MS, 0L)    /**     * Milliseconds remaining in the cooldown, or 0 if the cooldown has     * expired (or was never set). Exposed for UI to show "Try again in 18h".     */    fun cooldownRemainingMs(): Long {        val lastDenied = cooldownPrefs.getLong(KEY_LAST_DENIED_MS, 0L)        if (lastDenied == 0L) return 0L        val expiresAt = lastDenied + COOLDOWN_MS        val now = System.currentTimeMillis()        return (expiresAt - now).coerceAtLeast(0L)    }    /**     * Get the full permission state.     */    fun getPermissionState(): AccessibilityPermissionState {        return if (isAccessibilityEnabled()) {            AccessibilityPermissionState.GRANTED        } else {            AccessibilityPermissionState.NOT_GRANTED        }    }}// ──────────────────────────────────────────────────────────────────────────/** Accessibility permission states. */enum class AccessibilityPermissionState(val displayName: String) {    /** Service is enabled + connected. */    GRANTED("Granted"),    /** Service is not enabled (user hasn't enabled it in Settings). */    NOT_GRANTED("Not Granted");}